const createGalleryCardTemplate = ({ preview, original, description }) => `
  <li class="gallery-item">
  	<a class="gallery-link" href="${original}">
  		<img
  			class="gallery-image"
  			src="${preview}"
  			alt="${description}"
  			/>
  	</a>
  </li>
`;
const galleryCardsTemplate = images.map(createGalleryCardTemplate).join('');

const refs = {
  galleryList: document.querySelector('ul.gallery'),
};
refs.galleryList.innerHTML = galleryCardsTemplate;

new SimpleLightbox('.gallery a', {
  captionsData: 'alt',
  captionDelay: 250,
});
